import idle.core.*;import idle.core.upgrades.*;import idle.core.darkmatter.*;import idle.core.achievements.*;import idle.core.save.*;import idle.core.molecules.*;import java.util.*;import java.nio.file.*;
public class TestMatter{public static void main(String[]args)throws Exception{Game g=new Game(SaveCodec.read(Files.readString(Path.of(args[0]))).state(),Upgrades.DEFAULT,Automations.DEFAULT,DarkUpgrades.DEFAULT,Achievements.DEFAULT,new Random(1));System.out.println("space="+g.freeSpace()+" gas="+g.gatheredInState(Molecule.State.GAS));for(Molecule m:g.molecules())if(m.hasState()&&m.state()==Molecule.State.GAS&&g.hasSubstance(m.id()))System.out.printf("%s vol=%s count=%d can=%s next=%d\n",m.id(),g.moleculeVolume(m.id()),g.moleculeCount(m.id()),g.canCreateMolecule(m.id()),g.moleculesNextCreation(m.id()));boolean r=g.createMolecule("H2");System.out.println("CREATED="+r+" count="+g.moleculeCount("H2")+" gas="+g.gatheredInState(Molecule.State.GAS));}}
